(
  $fieldName := field.name;
  $dataPath := "filter." & $state.context.(
    $exists(joinTablePrefix) ? joinTablePrefix & "."
  ) & $fieldName;
  $label := $startCase($fieldName);

  $scalarMap := {
    "String": {
      "type": $fieldName = $state.context.component.parameterField ? 'parameter' : 'text',
      "parameterName": $fieldName = $state.context.component.parameterField ? 'id' : undefined,
      "dataPath": $dataPath & ($fieldName = $state.context.component.parameterField ? "._eq" : "._contains")
    },
    "Email": {
      "type": 'text',
      "dataPath": $dataPath & "._contains"
    },
    "Boolean": {
      "type": 'checkbox'
    },
    "DateTime": {
      "type": 'datetimeRange',
      "dataPath": $dataPath
    },
    "Int": [{
      "name": $fieldName & '.min',
      "label": $label & ' Min',
      "dataPath": $dataPath & '._gte',
      "type": 'integer'
    }, {
      "name": $fieldName & '.max',
      "label": $label & ' Max',
      "dataPath": $dataPath & '._lte',
      "type": 'integer'
    }],
    "Float": [{
      "name": $fieldName & '.min',
      "label": $label & ' Min',
      "dataPath": $dataPath & '._gte',
      "type": 'float'
    }, {
      "name": $fieldName & '.max',
      "label": $label & ' Max',
      "dataPath": $dataPath & '._lte',
      "type": 'float'
    }],
    "Measure": [
      {
        "name": $fieldName & '.min',
        "label": $label & ' Min',
        "dataPath": $dataPath & '.value._gte',
        "type": 'float'
      },
      {
        "name": $fieldName & '.max',
        "label": $label & ' Max',
        "dataPath": $dataPath & '.value._lte',
        "type": 'float'
      },
      {
        "name": $fieldName & '.unit',
        "type": 'combobox',
        "dataPath": $fieldName & '.unit',
        "target": {
          "dataPath": $dataPath & '.unit.id._in'
        },
        "label": $label & ' Unit',
        "multiselect": true,
        "api": 'Application',
        "queryType": 'Unit',
        "labelField": "name"
      }
    ],
    "RatioMeasure": [
      {
        "name": $fieldName & '.min',
        "label": $label & ' Min',
        "dataPath": $dataPath & '.numeratorValue._gte',
        "type": 'float'
      },
      {
        "name": $fieldName & '.max',
        "label": $label & ' Max',
        "dataPath": $dataPath & '.numeratorValue._lte',
        "type": 'float'
      },
      {
        "name": $fieldName & '.numeratorUnit',
        "type": 'combobox',
        "dataPath": $fieldName & '.numeratorUnit',
        "target": {
          "dataPath": $dataPath & '.numeratorUnit.id._in'
        },
        "label": $label & ' Numerator Unit',
        "multiselect": true,
        "api": 'Application',
        "queryType": 'Unit',
        "labelField": "name"
      },
      {
        "name": $fieldName & '.denominatorunit',
        "type": 'combobox',
        "dataPath": $fieldName & '.denominatorunit',
        "target": {
          "dataPath": $dataPath & '.denominatorunit.id._in'
        },
        "label": $label & ' Denominator Unit',
        "multiselect": true,
        "api": 'Application',
        "queryType": 'Unit',
        "labelField": "name"
      }
    ]
  };

  $format := $lookup($scalarMap, baseType);

  $map([$format ? $format : {}], function($v) {
    $merge([
      { 
        "name": $fieldName,
        "description": field.description,
        "label": $label,
        "type": "text",
        "dataPath": $dataPath & '._eq'
      },
      $v    
    ])
  })
)

(
  $activeFilter := function($fields){
    (
      $filteredFields := $filter($fields,function($v){
        $contains($v.name, "active") and $v.type = "Boolean!" ? true : false
      });

      $count($filteredFields) = 0 ? undefined :
      $count($filteredFields) = 1 ? {
        $filteredFields.name : {
          "_eq": true
        }
      } :
      $count($filteredFields) > 1 ? undefined
    )
  };

  $additionalFilter := $activeFilter(baseTypeModel.fields);

  {
    "name": field.name,
    "description": field.description,
    "label": $startCase(field.name),
    "labelField": $coalesce([baseTypeModel.metadata.mfgx.labelField, "id"]),
    "type": 'combobox',
    "dataPath": field.name,
    "target": {
      "dataPath": "filter." & 
        $state.context.(
          $exists(joinTablePrefix) ? joinTablePrefix & "."
        ) & 
        field.name & ".id._in"
    },
    "multiselect": true,
    "api": $state.context.parameters.api,
    "queryType": baseType,
    "additionalFilter":  $additionalFilter
  }
)

