(
  $standardFields := [
    'id',
    'createdAt',
    'createdByUser',
    'createdByUserId',
    'dataChanges',
    'updatedAt',
    'updatedByUser',
    'updatedByUserId',
    $state.context.component.parameterField
  ];

  $getFieldToExpand := function( $model) {(

    $joinField := $filter($model.fields, function($v) {
      $not($exists($standardFields[$=$v.name])) and 
      ($v.type = 'ID')
    });

    $count($joinField) > 1 ? $throw('Cannot determine a single join field');

    $expandField := $model.fields[
      metadata.mfgx.relation.fields.from =
      $joinField.name
    ];

    $isNil($expandField) ?
      $throw('Error generating the columns of the linked type.  
      The field, ' & $joinField.name & ', does not realize to a type.') :
      $expandField;

  )};

  $fieldToExpand := payload.component.model 
  ~> $getFieldToExpand;

  $baseTypeMatch := $match($fieldToExpand.type, /\[?(\w+)!?\]?!?/);
  $baseType := $baseTypeMatch.groups[0];

  $getBackReference := function( $model ){
    $model.fields[
      metadata.mfgx.relation.fields.from =
      $state.context.component.parameterField
    ]
  };

  $backReference := payload.component.model
  ~> $getBackReference;

  {
    "name": $fieldToExpand.name,
    "type": $baseType,
    "backReference": $backReference
  }
)

